    /**
     * Patched REND bytes for one photo. [activation] in 0..1 drives the strength records,
     * [headroomStops] the HDR-record; unknown inputs use the neutral mid-points.
     */
    fun renderingParameters(activation: Double, headroomStops: Double): ByteArray {
        val out = TEMPLATE.copyOf()
        val order = ByteOrder.LITTLE_ENDIAN
        val declared = ByteBuffer.wrap(out).order(order).getInt(8)
        require(declared == out.size && String(out, 0, 4, Charsets.US_ASCII) == "REND") { "REND template header invalid" }
        fun record(id: Int): Int {
            var cursor = HEADER
            while (cursor + 8 <= declared) {
                if (ByteBuffer.wrap(out, cursor, 2).order(order).short.toInt() and 0xffff == id) return cursor
                cursor += 8
            }
            error("REND template missing record 0x${id.toString(16)}")
        }
        fun write(cursor: Int, type: Int, value: Double) {
            val raw = when (type) {
                1 -> value.toFloat().toRawBits()
                2 -> value.roundToInt()
                3, 4 -> max(0.0, value).roundToInt()
                else -> error("REND record type $type unsupported")
            }
            ByteBuffer.wrap(out, cursor + 4, 4).order(order).putInt(raw)
        }
        val activation = min(max(activation, 0.0), 1.0)
        val headroom = max(headroomStops, 0.0)
        val secondary = activation * (min(headroom, 4.0) / 4.0)
        // XHLRB dynamic set; the profile follows the main camera's 1x constants.
        write(record(0x0190), 2, 50.0 * activation)
        write(record(0x0191), 1, 0.25 * activation)
        write(record(0x0192), 1, 12.0 * activation)
        write(record(0x0193), 1, 0.25 * activation)
        write(record(0x01c2), 1, 8.0 * secondary)
        write(record(0x01c3), 1, 20.0 * secondary)
        write(record(0x01c4), 1, 0.60 * secondary)
        write(record(0x01c5), 1, headroom)
        return out
    }

    /**
     * The activation input of the XHLRB fit: focus proximity, HDR headroom and scene
     * luminance feed the fitted gain the same way the reference pipeline derives it.
     */
    fun activation(focusNormalized: Double, headroomStops: Double): Double {
        val focus = min(max(focusNormalized, 0.0), 1.0)
        val headroomFactor = min(max(headroomStops, 0.0), 4.0) / 4.0
        val gain = 0.02 + 0.17 * focus + 0.04 * headroomFactor + 0.02 * 0.5
        return min(max(gain / 0.25, 0.02), 1.0)
    }
